const TXT = {"p/learn_L01": "هٰذا حَرْفُ الْأَلِفِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L01": "اُكْتُبْ حَرْفَ الْأَلِفِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L01": "أَيْنَ حَرْفُ الْأَلِفِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L01": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْأَلِفِ.", "p/forms_L01": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْأَلِفِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L01": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْأَلِفِ بِهٰذا الشَّكْلِ.", "p/color_L01": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْأَلِفِ.", "p/paint_L01": "لَوِّنْ حَرْفَ الْأَلِفِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L01": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْأَلِفِ فيها.", "p/blocks_L01": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْأَلِفِ.", "p/race_L01": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْأَلِفِ، وَانْطَلِقْ!", "p/learn_L02": "هٰذا حَرْفُ الْباءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L02": "اُكْتُبْ حَرْفَ الْباءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L02": "أَيْنَ حَرْفُ الْباءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L02": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْباءِ.", "p/forms_L02": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْباءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L02": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْباءِ بِهٰذا الشَّكْلِ.", "p/color_L02": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْباءِ.", "p/paint_L02": "لَوِّنْ حَرْفَ الْباءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L02": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْباءِ فيها.", "p/blocks_L02": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْباءِ.", "p/race_L02": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْباءِ، وَانْطَلِقْ!", "p/learn_L03": "هٰذا حَرْفُ التّاءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L03": "اُكْتُبْ حَرْفَ التّاءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L03": "أَيْنَ حَرْفُ التّاءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L03": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ التّاءِ.", "p/forms_L03": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ التّاءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L03": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ التّاءِ بِهٰذا الشَّكْلِ.", "p/color_L03": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ التّاءِ.", "p/paint_L03": "لَوِّنْ حَرْفَ التّاءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L03": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ التّاءِ فيها.", "p/blocks_L03": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ التّاءِ.", "p/race_L03": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ التّاءِ، وَانْطَلِقْ!", "p/learn_L04": "هٰذا حَرْفُ الثّاءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L04": "اُكْتُبْ حَرْفَ الثّاءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L04": "أَيْنَ حَرْفُ الثّاءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L04": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الثّاءِ.", "p/forms_L04": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الثّاءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L04": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الثّاءِ بِهٰذا الشَّكْلِ.", "p/color_L04": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الثّاءِ.", "p/paint_L04": "لَوِّنْ حَرْفَ الثّاءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L04": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الثّاءِ فيها.", "p/blocks_L04": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الثّاءِ.", "p/race_L04": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الثّاءِ، وَانْطَلِقْ!", "p/learn_L05": "هٰذا حَرْفُ الْجيمِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L05": "اُكْتُبْ حَرْفَ الْجيمِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L05": "أَيْنَ حَرْفُ الْجيمِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L05": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْجيمِ.", "p/forms_L05": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْجيمِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L05": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْجيمِ بِهٰذا الشَّكْلِ.", "p/color_L05": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْجيمِ.", "p/paint_L05": "لَوِّنْ حَرْفَ الْجيمِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L05": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْجيمِ فيها.", "p/blocks_L05": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْجيمِ.", "p/race_L05": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْجيمِ، وَانْطَلِقْ!", "p/learn_L06": "هٰذا حَرْفُ الْحاءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L06": "اُكْتُبْ حَرْفَ الْحاءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L06": "أَيْنَ حَرْفُ الْحاءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L06": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْحاءِ.", "p/forms_L06": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْحاءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L06": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْحاءِ بِهٰذا الشَّكْلِ.", "p/color_L06": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْحاءِ.", "p/paint_L06": "لَوِّنْ حَرْفَ الْحاءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L06": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْحاءِ فيها.", "p/blocks_L06": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْحاءِ.", "p/race_L06": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْحاءِ، وَانْطَلِقْ!", "p/learn_L07": "هٰذا حَرْفُ الْخاءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L07": "اُكْتُبْ حَرْفَ الْخاءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L07": "أَيْنَ حَرْفُ الْخاءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L07": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْخاءِ.", "p/forms_L07": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْخاءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L07": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْخاءِ بِهٰذا الشَّكْلِ.", "p/color_L07": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْخاءِ.", "p/paint_L07": "لَوِّنْ حَرْفَ الْخاءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L07": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْخاءِ فيها.", "p/blocks_L07": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْخاءِ.", "p/race_L07": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْخاءِ، وَانْطَلِقْ!", "p/learn_L08": "هٰذا حَرْفُ الدّالِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L08": "اُكْتُبْ حَرْفَ الدّالِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L08": "أَيْنَ حَرْفُ الدّالِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L08": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الدّالِ.", "p/forms_L08": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الدّالِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L08": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الدّالِ بِهٰذا الشَّكْلِ.", "p/color_L08": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الدّالِ.", "p/paint_L08": "لَوِّنْ حَرْفَ الدّالِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L08": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الدّالِ فيها.", "p/blocks_L08": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الدّالِ.", "p/race_L08": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الدّالِ، وَانْطَلِقْ!", "p/learn_L09": "هٰذا حَرْفُ الذّالِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L09": "اُكْتُبْ حَرْفَ الذّالِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L09": "أَيْنَ حَرْفُ الذّالِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L09": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الذّالِ.", "p/forms_L09": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الذّالِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L09": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الذّالِ بِهٰذا الشَّكْلِ.", "p/color_L09": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الذّالِ.", "p/paint_L09": "لَوِّنْ حَرْفَ الذّالِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L09": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الذّالِ فيها.", "p/blocks_L09": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الذّالِ.", "p/race_L09": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الذّالِ، وَانْطَلِقْ!", "p/learn_L10": "هٰذا حَرْفُ الرّاءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L10": "اُكْتُبْ حَرْفَ الرّاءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L10": "أَيْنَ حَرْفُ الرّاءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L10": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الرّاءِ.", "p/forms_L10": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الرّاءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L10": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الرّاءِ بِهٰذا الشَّكْلِ.", "p/color_L10": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الرّاءِ.", "p/paint_L10": "لَوِّنْ حَرْفَ الرّاءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L10": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الرّاءِ فيها.", "p/blocks_L10": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الرّاءِ.", "p/race_L10": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الرّاءِ، وَانْطَلِقْ!", "p/learn_L11": "هٰذا حَرْفُ الزّايِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L11": "اُكْتُبْ حَرْفَ الزّايِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L11": "أَيْنَ حَرْفُ الزّايِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L11": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الزّايِ.", "p/forms_L11": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الزّايِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L11": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الزّايِ بِهٰذا الشَّكْلِ.", "p/color_L11": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الزّايِ.", "p/paint_L11": "لَوِّنْ حَرْفَ الزّايِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L11": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الزّايِ فيها.", "p/blocks_L11": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الزّايِ.", "p/race_L11": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الزّايِ، وَانْطَلِقْ!", "p/learn_L12": "هٰذا حَرْفُ السّينِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L12": "اُكْتُبْ حَرْفَ السّينِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L12": "أَيْنَ حَرْفُ السّينِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L12": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ السّينِ.", "p/forms_L12": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ السّينِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L12": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ السّينِ بِهٰذا الشَّكْلِ.", "p/color_L12": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ السّينِ.", "p/paint_L12": "لَوِّنْ حَرْفَ السّينِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L12": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ السّينِ فيها.", "p/blocks_L12": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ السّينِ.", "p/race_L12": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ السّينِ، وَانْطَلِقْ!", "p/learn_L13": "هٰذا حَرْفُ الشّينِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L13": "اُكْتُبْ حَرْفَ الشّينِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L13": "أَيْنَ حَرْفُ الشّينِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L13": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الشّينِ.", "p/forms_L13": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الشّينِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L13": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الشّينِ بِهٰذا الشَّكْلِ.", "p/color_L13": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الشّينِ.", "p/paint_L13": "لَوِّنْ حَرْفَ الشّينِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L13": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الشّينِ فيها.", "p/blocks_L13": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الشّينِ.", "p/race_L13": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الشّينِ، وَانْطَلِقْ!", "p/learn_L14": "هٰذا حَرْفُ الصّادِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L14": "اُكْتُبْ حَرْفَ الصّادِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L14": "أَيْنَ حَرْفُ الصّادِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L14": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الصّادِ.", "p/forms_L14": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الصّادِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L14": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الصّادِ بِهٰذا الشَّكْلِ.", "p/color_L14": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الصّادِ.", "p/paint_L14": "لَوِّنْ حَرْفَ الصّادِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L14": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الصّادِ فيها.", "p/blocks_L14": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الصّادِ.", "p/race_L14": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الصّادِ، وَانْطَلِقْ!", "p/learn_L15": "هٰذا حَرْفُ الضّادِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L15": "اُكْتُبْ حَرْفَ الضّادِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L15": "أَيْنَ حَرْفُ الضّادِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L15": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الضّادِ.", "p/forms_L15": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الضّادِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L15": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الضّادِ بِهٰذا الشَّكْلِ.", "p/color_L15": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الضّادِ.", "p/paint_L15": "لَوِّنْ حَرْفَ الضّادِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L15": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الضّادِ فيها.", "p/blocks_L15": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الضّادِ.", "p/race_L15": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الضّادِ، وَانْطَلِقْ!", "p/learn_L16": "هٰذا حَرْفُ الطّاءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L16": "اُكْتُبْ حَرْفَ الطّاءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L16": "أَيْنَ حَرْفُ الطّاءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L16": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الطّاءِ.", "p/forms_L16": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الطّاءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L16": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الطّاءِ بِهٰذا الشَّكْلِ.", "p/color_L16": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الطّاءِ.", "p/paint_L16": "لَوِّنْ حَرْفَ الطّاءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L16": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الطّاءِ فيها.", "p/blocks_L16": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الطّاءِ.", "p/race_L16": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الطّاءِ، وَانْطَلِقْ!", "p/learn_L17": "هٰذا حَرْفُ الظّاءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L17": "اُكْتُبْ حَرْفَ الظّاءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L17": "أَيْنَ حَرْفُ الظّاءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L17": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الظّاءِ.", "p/forms_L17": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الظّاءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L17": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الظّاءِ بِهٰذا الشَّكْلِ.", "p/color_L17": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الظّاءِ.", "p/paint_L17": "لَوِّنْ حَرْفَ الظّاءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L17": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الظّاءِ فيها.", "p/blocks_L17": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الظّاءِ.", "p/race_L17": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الظّاءِ، وَانْطَلِقْ!", "p/learn_L18": "هٰذا حَرْفُ الْعَيْنِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L18": "اُكْتُبْ حَرْفَ الْعَيْنِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L18": "أَيْنَ حَرْفُ الْعَيْنِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L18": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْعَيْنِ.", "p/forms_L18": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْعَيْنِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L18": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْعَيْنِ بِهٰذا الشَّكْلِ.", "p/color_L18": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْعَيْنِ.", "p/paint_L18": "لَوِّنْ حَرْفَ الْعَيْنِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L18": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْعَيْنِ فيها.", "p/blocks_L18": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْعَيْنِ.", "p/race_L18": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْعَيْنِ، وَانْطَلِقْ!", "p/learn_L19": "هٰذا حَرْفُ الْغَيْنِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L19": "اُكْتُبْ حَرْفَ الْغَيْنِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L19": "أَيْنَ حَرْفُ الْغَيْنِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L19": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْغَيْنِ.", "p/forms_L19": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْغَيْنِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L19": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْغَيْنِ بِهٰذا الشَّكْلِ.", "p/color_L19": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْغَيْنِ.", "p/paint_L19": "لَوِّنْ حَرْفَ الْغَيْنِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L19": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْغَيْنِ فيها.", "p/blocks_L19": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْغَيْنِ.", "p/race_L19": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْغَيْنِ، وَانْطَلِقْ!", "p/learn_L20": "هٰذا حَرْفُ الْفاءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L20": "اُكْتُبْ حَرْفَ الْفاءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L20": "أَيْنَ حَرْفُ الْفاءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L20": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْفاءِ.", "p/forms_L20": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْفاءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L20": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْفاءِ بِهٰذا الشَّكْلِ.", "p/color_L20": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْفاءِ.", "p/paint_L20": "لَوِّنْ حَرْفَ الْفاءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L20": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْفاءِ فيها.", "p/blocks_L20": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْفاءِ.", "p/race_L20": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْفاءِ، وَانْطَلِقْ!", "p/learn_L21": "هٰذا حَرْفُ الْقافِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L21": "اُكْتُبْ حَرْفَ الْقافِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L21": "أَيْنَ حَرْفُ الْقافِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L21": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْقافِ.", "p/forms_L21": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْقافِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L21": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْقافِ بِهٰذا الشَّكْلِ.", "p/color_L21": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْقافِ.", "p/paint_L21": "لَوِّنْ حَرْفَ الْقافِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L21": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْقافِ فيها.", "p/blocks_L21": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْقافِ.", "p/race_L21": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْقافِ، وَانْطَلِقْ!", "p/learn_L22": "هٰذا حَرْفُ الْكافِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L22": "اُكْتُبْ حَرْفَ الْكافِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L22": "أَيْنَ حَرْفُ الْكافِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L22": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْكافِ.", "p/forms_L22": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْكافِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L22": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْكافِ بِهٰذا الشَّكْلِ.", "p/color_L22": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْكافِ.", "p/paint_L22": "لَوِّنْ حَرْفَ الْكافِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L22": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْكافِ فيها.", "p/blocks_L22": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْكافِ.", "p/race_L22": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْكافِ، وَانْطَلِقْ!", "p/learn_L23": "هٰذا حَرْفُ اللّامِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L23": "اُكْتُبْ حَرْفَ اللّامِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L23": "أَيْنَ حَرْفُ اللّامِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L23": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ اللّامِ.", "p/forms_L23": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ اللّامِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L23": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ اللّامِ بِهٰذا الشَّكْلِ.", "p/color_L23": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ اللّامِ.", "p/paint_L23": "لَوِّنْ حَرْفَ اللّامِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L23": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ اللّامِ فيها.", "p/blocks_L23": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ اللّامِ.", "p/race_L23": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ اللّامِ، وَانْطَلِقْ!", "p/learn_L24": "هٰذا حَرْفُ الْميمِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L24": "اُكْتُبْ حَرْفَ الْميمِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L24": "أَيْنَ حَرْفُ الْميمِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L24": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْميمِ.", "p/forms_L24": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْميمِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L24": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْميمِ بِهٰذا الشَّكْلِ.", "p/color_L24": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْميمِ.", "p/paint_L24": "لَوِّنْ حَرْفَ الْميمِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L24": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْميمِ فيها.", "p/blocks_L24": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْميمِ.", "p/race_L24": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْميمِ، وَانْطَلِقْ!", "p/learn_L25": "هٰذا حَرْفُ النّونِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L25": "اُكْتُبْ حَرْفَ النّونِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L25": "أَيْنَ حَرْفُ النّونِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L25": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ النّونِ.", "p/forms_L25": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ النّونِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L25": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ النّونِ بِهٰذا الشَّكْلِ.", "p/color_L25": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ النّونِ.", "p/paint_L25": "لَوِّنْ حَرْفَ النّونِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L25": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ النّونِ فيها.", "p/blocks_L25": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ النّونِ.", "p/race_L25": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ النّونِ، وَانْطَلِقْ!", "p/learn_L26": "هٰذا حَرْفُ الْهاءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L26": "اُكْتُبْ حَرْفَ الْهاءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L26": "أَيْنَ حَرْفُ الْهاءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L26": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْهاءِ.", "p/forms_L26": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْهاءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L26": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْهاءِ بِهٰذا الشَّكْلِ.", "p/color_L26": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْهاءِ.", "p/paint_L26": "لَوِّنْ حَرْفَ الْهاءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L26": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْهاءِ فيها.", "p/blocks_L26": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْهاءِ.", "p/race_L26": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْهاءِ، وَانْطَلِقْ!", "p/learn_L27": "هٰذا حَرْفُ الْواوِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L27": "اُكْتُبْ حَرْفَ الْواوِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L27": "أَيْنَ حَرْفُ الْواوِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L27": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْواوِ.", "p/forms_L27": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْواوِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L27": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْواوِ بِهٰذا الشَّكْلِ.", "p/color_L27": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْواوِ.", "p/paint_L27": "لَوِّنْ حَرْفَ الْواوِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L27": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْواوِ فيها.", "p/blocks_L27": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْواوِ.", "p/race_L27": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْواوِ، وَانْطَلِقْ!", "p/learn_L28": "هٰذا حَرْفُ الْياءِ. اِسْتَمِعْ إِلى أَصْواتِهِ، وَتَعَرَّفْ عَلى أَشْكالِهِ.", "p/write_L28": "اُكْتُبْ حَرْفَ الْياءِ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "p/pos_L28": "أَيْنَ حَرْفُ الْياءِ في هٰذِهِ الْكَلِمَةِ؟ في أَوَّلِها، أَمْ في وَسَطِها، أَمْ في آخِرِها؟", "p/sort_L28": "ضَعْ كُلَّ كُرَةٍ في الْمَرْمى الْمُناسِبِ، حَسَبَ مَوْضِعِ حَرْفِ الْياءِ.", "p/forms_L28": "أَكْمِلِ الْكَلِمَةَ بِشَكْلِ حَرْفِ الْياءِ الْمُناسِبِ، مِنْ تُفّاحاتِ الشَّجَرَةِ.", "p/fish_L28": "صِدِ الْأَسْماكَ الَّتي فيها حَرْفُ الْياءِ بِهٰذا الشَّكْلِ.", "p/color_L28": "لَوِّنِ الْكُراتِ الَّتي فيها كَلِماتٌ تَبْدَأُ بِحَرْفِ الْياءِ.", "p/paint_L28": "لَوِّنْ حَرْفَ الْياءِ بِأَلْوانِكَ الْجَميلَةِ.", "p/match_L28": "ساعِدْ سْبايْدَرْمان! وَصِّلْ كُلَّ صورَةٍ بِشَكْلِ حَرْفِ الْياءِ فيها.", "p/blocks_L28": "اِكْسِرِ الْمُكَعَّباتِ الَّتي فيها حَرْفُ الْياءِ.", "p/race_L28": "اِخْتَرِ السَّيّارَةَ الَّتي تَحْمِلُ صورَةً فيها حَرْفُ الْياءِ، وَانْطَلِقْ!", "g/welcome": "أَهْلًا وَسَهْلًا بِكَ في لُغَتي مَعَ أُسْتاذِ أَحْمَد! اِخْتَرْ حَرْفًا، وَهَيّا نَلْعَبُ وَنَتَعَلَّمُ.", "g/pick": "اِخْتَرْ لُعْبَةً، وَهَيّا نَبْدَأُ!", "g/kick": "اِسْمَعِ الصَّوْتَ، وَسَدِّدِ الْكُرَةَ إِلى الْمَرْمى الصَّحيحِ.", "g/order": "رَتِّبِ الْحُروفَ، لِتُكَوِّنَ كَلِمَةً تَدُلُّ عَلى الصّورَةِ.", "g/split": "حَلِّلِ الْكَلِمَةَ، وَضَعْ كُلَّ حَرْفٍ في نَجْمَةٍ.", "g/pencils": "رَتِّبِ الْأَقْلامَ حَسَبَ أَرْقامِها، وَكَوِّنْ كَلِمَةً.", "g/miss": "اُكْتُبِ الْحَرْفَ النّاقِصَ في الْكَلِمَةِ، بِالْقَلَمِ.", "g/dict": "اِسْمَعْ، وَاكْتُبْ بِالْقَلَمِ.", "g/wordw": "اُكْتُبِ الْكَلِمَةَ بِالْقَلَمِ، فَوْقَ النُّقَطِ.", "g/start": "في أَوَّلِ الْكَلِمَةِ.", "g/middle": "في وَسَطِ الْكَلِمَةِ.", "g/end": "في آخِرِ الْكَلِمَةِ.", "g/alone": "وَحْدَهُ.", "g/tour": "جَوْلَةُ الْأَبْطالِ! أَلْعابٌ مُنَوَّعَةٌ، هَيّا بِنا!", "g/c1": "أَحْسَنْتَ!", "g/c2": "مُمْتاز!", "g/c3": "رائِعٌ يا بَطَل!", "g/c4": "بَطَل!", "g/c5": "عَبْقَرِيّ!", "g/c6": "شاطِر!", "g/c7": "أَنْتَ نَجْم!", "g/c8": "واو! إِجابَةٌ صَحيحَة!", "g/c9": "كَفو يا بَطَل!", "g/c10": "عاشَ يا بَطَل!", "g/c11": "يا سَلام عَلَيْك!", "g/c12": "هٰكَذا يَكونُ الْأَبْطال!", "g/goal": "هَدَف! هَدَفٌ رائِع!", "g/w1": "حاوِلْ مَرَّةً أُخْرى.", "g/w2": "قَريب! جَرِّبْ مَرَّةً ثانِيَة.", "g/w3": "فَكِّرْ جَيِّدًا، أَنْتَ تَسْتَطيع.", "g/w4": "لا بَأْس، نُحاوِلُ مَعًا.", "g/w5": "اِنْتَبِهْ لِلْحَرْفِ جَيِّدًا.", "g/guide": "اُكْتُبْ فَوْقَ النُّقَطِ، وَسَتَنْجَح.", "g/wgood": "خَطٌّ جَميل! كِتابَةٌ رائِعَة.", "g/done1": "أَنْهَيْتَ اللُّعْبَةَ، أَحْسَنْت!", "g/done2": "رائِع! أَنْتَ بَطَلُ الْحُروف!", "g/done3": "مُمْتاز! هَيّا إِلى لُعْبَةٍ أُخْرى.", "g/paintdone": "لَوْحَةٌ جَميلَة! أَنْتَ فَنّان.", "g/fishdone": "صِدْتَ كُلَّ الْأَسْماك!", "g/blocksdone": "كَسَرْتَ كُلَّ الْمُكَعَّبات!", "g/racewin": "فُزْتَ بِالسِّباق!", "g/spidey": "شُكْرًا لَك! ساعَدْتَ سْبايْدَرْمان.", "g/tourdone": "أَنْهَيْتَ جَوْلَةَ الْأَبْطال! أَنْتَ بَطَلُ الْحُروف."};
